R_API int r_strbuf_appendf(RStrBuf *sb, const char *fmt, ...) { /* <=== r_strbuf_appendf */ 
	int ret;
	char string[1024];
	va_list ap;

	va_start (ap, fmt);
	ret = vsnprintf (string, sizeof (string) - 1, fmt, ap);
	if (ret >= sizeof (string)) {
		char *p = malloc (ret + 2);
		if (!p) {
			va_end (ap);
			return false;
		}
		*p = 0;
		va_start (ap, fmt);
		(void)vsnprintf (p, ret, fmt, ap);
		ret = r_strbuf_append (sb, p);
		free (p);
	} else {
		string[ret] = 0;
		ret = r_strbuf_append (sb, string);
	}
	va_end (ap);
	return ret;
}

